+const fs = require('fs');
+const path = require('path');
+const Ajv2019 = require('ajv-draft-04'); // draft-04 schema
+const AjvDraft04 = require('ajv-draft-04');
+const yaml = (()=>{try{return require('js-yaml')}catch(e){return null}})();
+
+const schema = JSON.parse(fs.readFileSync('src/schemas/json/bamboo-spec.json','utf8'));
+const ajv = new AjvDraft04({strict:false, allErrors:false});
+let validate;
+try { validate = ajv.compile(schema); } catch(e){ console.log('COMPILE ERROR', e.message); process.exit(1);}
+
+const dir='src/test/bamboo-spec';
+let fail=0;
+for(const f of fs.readdirSync(dir)){
+  const p=path.join(dir,f);
+  let data;
+  if(f.endsWith('.json')) data=JSON.parse(fs.readFileSync(p,'utf8'));
+  else if(f.endsWith('.yml')||f.endsWith('.yaml')){ if(!yaml){console.log('no yaml lib');process.exit(1);} data=yaml.load(fs.readFileSync(p,'utf8')); }
+  else continue;
+  const ok=validate(data);
+  if(!ok){ fail++; console.log('FAIL',f); console.log(JSON.stringify(validate.errors,null,1).slice(0,1500)); }
+  else console.log('PASS',f);
+}
+console.log(fail?('FAILURES:'+fail):'ALL PASS');
